  int numSizes = prices.size();
  vector<int> maxProfit(numSizes);
  vector<vector<int>> solutions;
  for (int size = 0; size < numSizes; size++) {
    solutions.push_back({});
  }

  for (int size = 0; size < numSizes; size++) {
    for (int dividingPoint = 0; dividingPoint <= size; dividingPoint++) {
      int possibleProfit =
